subsection.code_block:
#include <cstdint>
#include <cstring>
#include <string>
#include <vector>

#pragma pack(push, 1)
struct studiohdr_t {
    char id[4];             // FourCC "IDST"
    int32_t version;        // Versión 10 en GoldSrc
    char name[64];          // Nombre interno del modelo
    int32_t length;         // Tamaño del archivo binario
    float eyeposition[3];    
    float min[3];            
    float max[3];            
    float bbmin[3];          
    float bbmax[3];          
    int32_t flags;          
    int32_t numbones;       
    int32_t boneindex;      
    int32_t numseq;         // Número de secuencias de animación
    int32_t seqindex;       // Desplazamiento al arreglo mstudioseqdesc_t
};

struct mstudioseqdesc_t {
    char label[32];         // Nombre de la secuencia (ej. "reload")
    float fps;              // Cuadros por segundo
    int32_t flags;          
    int32_t numevents;      // Cantidad de eventos
    int32_t eventindex;     // Desplazamiento al arreglo mstudioevent_t
    int32_t numblends;
    int32_t animindex;
};

struct mstudioevent_t {
    int32_t frame;          // Cuadro exacto de ejecución
    int32_t event;          // ID del evento (5004 = Sonido de cliente)
    int32_t type;
    char options[64];       // Ruta relativa del archivo de audio WAV
};
#pragma pack(pop)

struct ModelDependencyGraph {
    std::string model_path;
    std::vector<std::string> sound_dependencies;
    std::vector<std::string> texture_dependencies;
};

ModelDependencyGraph ParseGoldSrcDependencies(const uint8_t* buffer, size_t size) {
    ModelDependencyGraph graph;
    if (size < sizeof(studiohdr_t)) return graph;

    const auto* header = reinterpret_cast<const studiohdr_t*>(buffer);

    if (std::memcmp(header->id, "IDST", 4) != 0 || header->version != 10) {
        return graph;
    }

    const auto* sequences = reinterpret_cast<const mstudioseqdesc_t*>(buffer + header->seqindex);

    for (int i = 0; i < header->numseq; ++i) {
        const auto& seq = sequences[i];
        if (seq.numevents == 0) continue;

        const auto* events = reinterpret_cast<const mstudioevent_t*>(buffer + seq.eventindex);

        for (int j = 0; j < seq.numevents; ++j) {
            const auto& evt = events[j];

            // Evento 5004: Reproducción de sonido de cliente en GoldSrc
            if (evt.event == 5004) {
                std::string sound_path(evt.options);
                if (!sound_path.empty()) {
                    graph.sound_dependencies.push_back("sound/" + sound_path);
                }
            }
        }
    }

    return graph;
}
